<!doctype html>
<html><head><meta charset="utf-8"><title>Payslip {{ $transaction->employee->employee_no }}</title><style>body{font-family:DejaVu Sans, sans-serif;color:#172033;font-size:12px}h1{font-size:22px;margin:0}.header{border-bottom:2px solid #2563eb;padding-bottom:14px;margin-bottom:18px}.muted{color:#64748b}.grid{display:grid;grid-template-columns:1fr 1fr;gap:8px 30px;margin-bottom:18px}.row{display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px solid #e5e7eb}.total{font-weight:bold;background:#eff6ff;padding:10px}.right{text-align:right}</style></head><body><div class="header"><h1>{{ $transaction->employee->tenant->company_name }}</h1><div class="muted">Payroll payslip · {{ $transaction->period->name }}</div></div><div class="grid"><div><strong>Employee</strong><br>{{ $transaction->employee->full_name }}</div><div><strong>Employee No.</strong><br>{{ $transaction->employee->employee_no }}</div><div><strong>Department</strong><br>{{ $transaction->employee->department?->name ?? '—' }}</div><div><strong>Payroll status</strong><br>{{ $transaction->status }}</div></div><h3>Earnings and deductions</h3><div class="row"><span>Basic salary</span><span>{{ number_format($transaction->basic_salary,2) }}</span></div><div class="row"><span>Allowances</span><span>{{ number_format($transaction->allowances,2) }}</span></div><div class="row"><strong>Gross pay</strong><strong>{{ number_format($transaction->gross_pay,2) }}</strong></div><br><div class="row"><span>PAYE</span><span>{{ number_format($transaction->paye,2) }}</span></div><div class="row"><span>NSSF</span><span>{{ number_format($transaction->nssf,2) }}</span></div><div class="row"><span>SHIF</span><span>{{ number_format($transaction->shif,2) }}</span></div><div class="row"><span>Housing levy</span><span>{{ number_format($transaction->housing_levy,2) }}</span></div><div class="row"><strong>Total deductions</strong><strong>{{ number_format($transaction->total_deductions,2) }}</strong></div><div class="row total"><span>Net pay (KES)</span><span>{{ number_format($transaction->net_pay,2) }}</span></div><p class="muted">Generated by BluePrint HR. Statutory amounts are based on the tenant’s configured rate set.</p></body></html>
